#!/usr/bin/env bash
# Offline tests of 1.7.0 — clips of findings (references/clips.md), no network, no browser: clips.py (finalize on a clip
# generated by ffmpeg, check, viewed, policy, sheet, caps, settings, ignore), ingest_findings.py with clips, build_report.py
# «Ролики находок», render_draft.py (viewed clips only), publish_shots.py local, export_results.py --clips, check_env
# (ffmpeg rows), intake.py («с видео» / «без видео»), finding schema, attachment limit of web_upload_lib.mjs.
# Without ffmpeg the video checks are SKIP. Browser part — tests/test_v170_browser.sh.
set -uo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; S="$HERE/../scripts"
if command -v python3 >/dev/null 2>&1; then PY="${PY:-python3}"; else PY="${PY:-python}"; fi
export PYTHONDONTWRITEBYTECODE=1
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
pass=0; fail=0; skip=0
ok(){ echo "PASS $1"; pass=$((pass+1)); }; bad(){ echo "FAIL $1"; fail=$((fail+1)); }; sk(){ echo "SKIP $1"; skip=$((skip+1)); }
check(){ local name="$1"; shift; if "$@"; then ok "$name"; else bad "$name"; fi; }
CL="$S/clips.py"
HAVE_FF=0; command -v ffmpeg >/dev/null 2>&1 && command -v ffprobe >/dev/null 2>&1 && HAVE_FF=1
[ -n "${QA_FFMPEG:-}" ] && [ -x "${QA_FFMPEG}" ] && HAVE_FF=1

for f in clips export_results gitignore_helper; do
  check "syntax $f.py" "$PY" -c "import ast,sys; ast.parse(open(sys.argv[1],encoding='utf-8').read())" "$S/$f.py"
done

# ---------- settings, policy, caps (no video) ----------
check "clips.py settings: умолчания qa_clips (auto, 10 с, 3 МБ, both)" sh -c "
  '$PY' '$CL' settings | '$PY' -c \"import json,sys; s=json.load(sys.stdin); assert (s['mode'],s['max_seconds'],s['max_mb'],s['format'])==('auto',10.0,3.0,'both'), s\""
R0="$TMP/run0"; mkdir -p "$R0"; printf 'version: 1\nclips:\n  mode: off\n  max_mb: 2\n' > "$R0/run-config.yaml"
check "clips.py settings <RUN_DIR>: ключи clips: из run-config" sh -c "
  '$PY' '$CL' settings '$R0' | '$PY' -c \"import json,sys; s=json.load(sys.stdin); assert s['mode']=='off' and s['max_mb']==2.0, s\""
check "clips.py policy: мерцание → ролик, контраст → нет; clips.mode=off из run-config → нет; --mode on → да" sh -c "
  '$PY' '$CL' policy 'Меню мерцает и закрывается само' | grep -q '\"record\": true' &&
  '$PY' '$CL' policy 'Контраст текста 3,1:1' | grep -q '\"record\": false' &&
  '$PY' '$CL' policy 'Меню мерцает' --run-dir '$R0' | grep -q 'clips.mode=off' &&
  '$PY' '$CL' policy 'Опечатка' --mode on | grep -q '\"record\": true'"
check "clips.py caps --json: ffmpeg/ffprobe и Playwright screencast" sh -c "
  '$PY' '$CL' caps --json | '$PY' -c \"import json,sys; c=json.load(sys.stdin); assert 'ffmpeg' in c and 'playwright' in c and 'screencast' in c['playwright'] and c['recording'], c\""
check "clips.py ignore: clips/ и recordings/ в <RUN_DIR>/.gitignore (идемпотентно)" sh -c "
  '$PY' '$CL' ignore '$R0' >/dev/null && '$PY' '$CL' ignore '$R0' >/dev/null &&
  test \$(grep -c '^clips/\$' '$R0/.gitignore') = 1 && grep -q '^recordings/\$' '$R0/.gitignore'"
check "gitignore_helper.py clips <RUN_DIR>: то же через помощник .gitignore; ensure/check работают как раньше" sh -c "
  mkdir -p '$TMP/gi' && '$PY' '$S/gitignore_helper.py' clips '$TMP/gi' >/dev/null && grep -q '^clips/\$' '$TMP/gi/.gitignore' &&
  '$PY' '$S/gitignore_helper.py' check '$TMP/gi' --json >/dev/null; test \$? -le 1"
check "clips.py finalize: нет исходника → код 2, ничего не создано" sh -c "
  '$PY' '$CL' finalize '$R0' --src '$TMP/none.webm' --name F-001-x >/dev/null; test \$? = 2 && test ! -d '$R0/clips'"

# ---------- intake, run-config, schema ----------
check "intake.py: «с видео» → on, «без видео» → off, иначе auto; блок clips: с умолчаниями" sh -c "
  '$PY' '$S/intake.py' from-text --text 'Протестируй https://example.com с видео' --json | '$PY' -c \"import json,sys; c=json.load(sys.stdin)['config']['clips']; assert c['mode']=='on' and c['max_mb']==3.0 and c['mask']==[], c\" &&
  '$PY' '$S/intake.py' from-text --text 'Проверь https://example.com без видео' --json | '$PY' -c \"import json,sys; assert json.load(sys.stdin)['config']['clips']['mode']=='off'\" &&
  '$PY' '$S/intake.py' from-text --text 'Проверь видеоплеер на https://example.com' --json | '$PY' -c \"import json,sys; assert json.load(sys.stdin)['config']['clips']['mode']=='auto'\" &&
  '$PY' '$S/intake.py' from-text --text 'QA https://example.com and record clips' --json | '$PY' -c \"import json,sys; assert json.load(sys.stdin)['config']['clips']['mode']=='on'\""
check "intake.py автопилот: решение «ролики находок: auto» в журнале решений; YAML черновика читается miniyaml" sh -c "
  '$PY' '$S/intake.py' from-text --text 'https://example.com автопилот' --json | grep -q 'ролики находок: auto' &&
  '$PY' '$S/intake.py' from-text --text 'https://example.com с видео' > '$TMP/rc.yaml' &&
  '$PY' '$S/shared/miniyaml.py' '$TMP/rc.yaml' | '$PY' -c \"import json,sys; assert json.load(sys.stdin)['clips']['mode']=='on'\""
check "run-config.example.yaml: блок clips: (mode auto, max_mb 3, mask [])" sh -c "
  '$PY' '$S/shared/miniyaml.py' '$HERE/../templates/run-config.example.yaml' | '$PY' -c \"import json,sys; c=json.load(sys.stdin)['clips']; assert c['mode']=='auto' and c['max_mb']==3 and c['mask']==[], c\""
check "finding.schema.json: clips (записи и пути) и recordings — валидно; clips: [{kind: bad}] — ошибка" "$PY" - "$S" "$HERE/../templates/finding.schema.json" <<'EOF'
import json, sys
sys.path.insert(0, sys.argv[1] + "/shared")
import qa_ingest
root, fdef = qa_ingest.finding_schema(sys.argv[2])
base = {"direction": "functional", "check_id": "functional.menu", "type": "bug", "severity": "medium", "title": "t", "url": "https://example.com/",
        "steps": ["a"], "expected": "e", "actual": "a", "sources": ["own:checklist"]}
good = dict(base, clips=["clips/F-1.mp4", {"file": "clips/F-1.mp4", "kind": "after", "audio": False, "viewed": True, "steps": ["x"]}], recordings=["clips/F-1.mp4"])
errs = []; qa_ingest.schema_check(good, fdef, root, "f", errs); assert not errs, errs
errs = []; qa_ingest.schema_check(dict(base, clips=[{"file": "x.mp4", "kind": "bad"}]), fdef, root, "f", errs); assert errs, "kind"
errs = []; qa_ingest.schema_check(dict(base, clips=[{"kind": "error"}]), fdef, root, "f", errs); assert errs, "file"
EOF

# ---------- attachment limit (publish_web / comment_web) ----------
if command -v node >/dev/null 2>&1; then
  check "web_upload_lib: .mp4/.webm принимаются, > 10 МБ — отказ до браузера (понятный текст), --max-attach-mb поднимает лимит; ссылка-ролик → плейсхолдер" \
    node --input-type=module -e "
    import fs from 'node:fs'; import * as L from '$S/node/web_upload_lib.mjs';
    const d = process.argv[1]; fs.writeFileSync(d + '/a.mp4', Buffer.alloc(1000)); fs.writeFileSync(d + '/big.mp4', Buffer.alloc(11 * 1048576));
    L.checkShots([d + '/a.mp4']);
    let stopped = null; try { L.checkShots([d + '/big.mp4']); } catch (e) { stopped = e; }
    if (!stopped || !/10 МБ/.test(stopped.message) || !/Ничего не загружено/.test(stopped.message)) throw new Error('no stop: ' + (stopped && stopped.message));
    L.checkShots([d + '/big.mp4'], 20);
    const b = L.preparePlaceholders('x\n[▶ ролик, 4 с, 0,1 МБ](../../clips/a.mp4) — cap\n', [d + '/a.mp4']);
    if (!b.includes('{{qa-shot:a.mp4}} — cap')) throw new Error(b);
    const p = L.preparePlaceholders('[link](../../screenshots/s.png)\n', ['/x/s.png']);
    if (!p.includes('[link](../../screenshots/s.png)')) throw new Error('png link must stay: ' + p);
  " "$TMP"
else sk "web_upload_lib: нет node"; fi

# ---------- video (ffmpeg) ----------
if [ $HAVE_FF -eq 1 ]; then
  R="$TMP/run"; mkdir -p "$R/screenshots"
  printf 'version: 1\nsite:\n  allowed_domains: [example.com]\n' > "$R/run-config.yaml"
  ffmpeg -v error -y -f lavfi -i testsrc=size=1280x720:rate=25 -f lavfi -i sine=frequency=440 -t 4 -c:v libvpx -b:v 2M -c:a libopus "$TMP/raw.webm" 2>/dev/null \
    || ffmpeg -v error -y -f lavfi -i testsrc=size=1280x720:rate=25 -t 4 -c:v libvpx -b:v 2M "$TMP/raw.webm"
  cp "$TMP/raw.webm" "$TMP/raw2.webm"
  touch "$R/screenshots/F-001-menu-annotated.png"
  cat > "$R/findings.json" <<'EOF'
{"run": {"id": "2026-10-10-example.com", "site": "https://example.com/", "depth": "smoke", "mode": "dry-run", "started_at": "2026-10-10T10:00:00Z"}, "findings": [
 {"id": "F-001", "direction": "functional", "check_id": "functional.menu", "type": "bug", "severity": "medium", "title": "Меню закрывается само",
  "url": "https://example.com/", "steps": ["Нажать «Меню»"], "expected": "Меню открыто", "actual": "Закрывается через 0,6 с",
  "screenshots": ["screenshots/F-001-menu-annotated.png"], "sources": ["own:checklist"], "fingerprint": "0123456789abcdef"}]}
EOF
  "$PY" "$S/build_report.py" report "$R" >/dev/null
  check "build_report: без роликов раздела «Ролики находок» нет" sh -c "! grep -q 'Ролики находок' '$R/report.md'"
  "$PY" "$CL" finalize "$R" --src "$TMP/raw.webm" --name F-001-menu --caption "Меню закрывается через 0,6 с" --finding F-001 \
    --step "Нажать «Меню»" > "$TMP/fin.json"; c=$?
  check "clips.py finalize: код 0, mp4 ≤ 3 МБ, без звука (ffprobe), GIF, постер, лента кадров; запись в находке и recordings[]" sh -c "
    test $c = 0 && test -s '$R/clips/F-001-menu.mp4' && test -s '$R/clips/F-001-menu-sheet.png' && test -s '$R/clips/F-001-menu-poster.png' &&
    test -s '$R/clips/F-001-menu.gif' && test \$(wc -c < '$R/clips/F-001-menu.mp4') -le 3145728 &&
    test -z \"\$(ffprobe -v error -select_streams a -show_entries stream=index -of csv=p=0 '$R/clips/F-001-menu.mp4')\" &&
    '$PY' -c \"import json,sys; f=json.load(open(sys.argv[1]))['findings'][0]; c=f['clips'][0]
assert c['file']=='clips/F-001-menu.mp4' and c['audio'] is False and c['viewed'] is False and c['codec']=='h264', c
assert c['sheet']=='clips/F-001-menu-sheet.png' and c['steps']==['Нажать «Меню»'] and c['sha256'] and f['recordings']==['clips/F-001-menu.mp4'], f\" '$R/findings.json' &&
    grep -q '^clips/\$' '$R/.gitignore'"
  check "clips.py finalize: исходник вне <RUN_DIR> не удаляется (сырой файл — во временной папке)" test -s "$TMP/raw.webm"
  check "clips.py check: непросмотренный → код 1 «не просмотрен»" sh -c "'$PY' '$CL' check '$R' > '$TMP/chk.out'; c=\$?; test \$c = 1 && grep -q 'не просмотрен' '$TMP/chk.out'"
  check "render_draft: непросмотренный ролик в черновик не идёт" sh -c "! '$PY' '$S/render_draft.py' detailed '$R/findings.json' --id F-001 | grep -q 'ролик'"
  check "publish_shots local: непросмотренный ролик не прикладывается (skipped: не просмотрен)" sh -c "
    '$PY' '$S/publish_shots.py' local '$R' 2>/dev/null | '$PY' -c \"import json,sys; d=json.load(sys.stdin); assert not any(r['file'].startswith('clips/') for r in d['files']) and any('не просмотрен' in s['reason'] for s in d['skipped']), d\""
  check "clips.py viewed: ставит viewed и viewed_at (лента есть); check → код 0" sh -c "
    '$PY' '$CL' viewed '$R' --id F-001 >/dev/null && '$PY' '$CL' check '$R' >/dev/null &&
    '$PY' -c \"import json,sys; c=json.load(open(sys.argv[1]))['findings'][0]['clips'][0]; assert c['viewed'] is True and c['viewed_at'], c\" '$R/findings.json'"
  check "clips.py list и sheet --id: лента пересобирается" sh -c "
    '$PY' '$CL' list '$R' | grep -q 'просмотрен  clips/F-001-menu.mp4' && rm '$R/clips/F-001-menu-sheet.png' &&
    '$PY' '$CL' sheet '$R' --id F-001 >/dev/null && test -s '$R/clips/F-001-menu-sheet.png'"
  cp "$R/clips/F-001-menu.mp4" "$TMP/backup.mp4"; printf 'x' >> "$R/clips/F-001-menu.mp4"
  check "clips.py check/viewed: файл изменён после записи → sha256 не совпал" sh -c "
    '$PY' '$CL' check '$R' | grep -q 'sha256' && ! '$PY' '$CL' viewed '$R' --id F-001 >/dev/null"
  cp "$TMP/backup.mp4" "$R/clips/F-001-menu.mp4"
  "$PY" "$S/build_report.py" report "$R" >/dev/null; "$PY" "$S/build_report.py" summary "$R" >/dev/null
  check "build_report: раздел «Ролики находок» в report.md и summary.md (вид, длительность, размер, файл, постер)" sh -c "
    grep -q '^## Ролики находок' '$R/report.md' && grep -q '^## Ролики находок' '$R/summary.md' &&
    grep -q '| F-001 — Меню закрывается через 0,6 с | ошибка | 4 с | ' '$R/report.md' && grep -q '(clips/F-001-menu.mp4)' '$R/report.md' &&
    grep -q '(clips/F-001-menu-poster.png) | да |' '$R/report.md'"
  check "render_draft: просмотренный ролик — GIF inline и «▶ ролик, 4 с, … МБ»; --screenshot-base — из той же ветки" sh -c "
    '$PY' '$S/render_draft.py' detailed '$R/findings.json' --id F-001 > '$TMP/d1.md' &&
    grep -q '!\[Меню закрывается через 0,6 с\](clips/F-001-menu.gif)' '$TMP/d1.md' && grep -q '\[▶ ролик, 4 с, 0,[0-9]* МБ\](clips/F-001-menu.mp4)' '$TMP/d1.md' &&
    '$PY' '$S/render_draft.py' detailed '$R/findings.json' --id F-001 --screenshot-base https://github.com/o/r/blob/qa/p | grep -q '(https://github.com/o/r/blob/qa/p/F-001-menu.mp4?raw=true)'"
  check "render_draft group: ссылка на ролик в ячейке «Скриншот»" sh -c "
    '$PY' -c \"import json,sys; d=json.load(open(sys.argv[1])); f=dict(d['findings'][0]); f.update(id='F-002', fingerprint='fedcba9876543210', title='Вторая'); d['findings'].append(f); json.dump(d, open(sys.argv[2],'w'), ensure_ascii=False)\" '$R/findings.json' '$TMP/f2.json' &&
    '$PY' '$S/render_draft.py' group '$TMP/f2.json' --ids F-001,F-002 | grep -q '<br>\[▶ ролик'"
  check "publish_shots local: просмотренные mp4 и GIF → results/clips/ и архив (clips/…)" sh -c "
    '$PY' '$S/publish_shots.py' local '$R' >/dev/null 2>&1 && test -s '$R/results/clips/F-001-menu.mp4' && test -s '$R/results/clips/F-001-menu.gif' &&
    '$PY' -c \"import zipfile,sys; n=zipfile.ZipFile(sys.argv[1]).namelist(); assert 'clips/F-001-menu.mp4' in n and 'F-001-menu-annotated.png' in n, n\" '$R/results/screenshots.zip'"
  check "export_results --clips referenced (по умолчанию): mp4, GIF, постер в <dest>/clips/; лента — нет" sh -c "
    '$PY' '$S/export_results.py' '$R' --to '$TMP/out1' >/dev/null 2>&1 && D='$TMP/out1/run' &&
    test -s \$D/clips/F-001-menu.mp4 && test -s \$D/clips/F-001-menu.gif && test -s \$D/clips/F-001-menu-poster.png && test ! -e \$D/clips/F-001-menu-sheet.png"
  check "export_results --clips all: вся папка clips/ (с лентой); --clips none: без роликов; неверное значение — код 2" sh -c "
    '$PY' '$S/export_results.py' '$R' --to '$TMP/out2' --clips all --json | '$PY' -c \"import json,sys; f=[r['file'] for r in json.load(sys.stdin)['files']]; assert 'clips/F-001-menu-sheet.png' in f, f\" &&
    '$PY' '$S/export_results.py' '$R' --to '$TMP/out3' --clips none --json | '$PY' -c \"import json,sys; f=[r['file'] for r in json.load(sys.stdin)['files']]; assert not any(x.startswith('clips/') for x in f), f\" &&
    { '$PY' '$S/export_results.py' '$R' --to '$TMP/out4' --clips some >/dev/null 2>&1; test \$? = 2; }"
  # ingest: a path inside RUN_DIR becomes an entry; outside / not a clip / missing — dropped with a warning
  cp "$TMP/raw2.webm" "$R/clips/T-01-raw.webm"; cp "$TMP/raw2.webm" "$TMP/outside.mp4"
  cat > "$TMP/msg.md" <<'EOF'
Готово.
```qa-findings
{"thread": "qa-ux", "findings": [
 {"direction": "ux", "check_id": "ux.feedback", "type": "bug", "severity": "low", "title": "Тост исчезает мгновенно", "url": "https://example.com/a",
  "steps": ["Сохранить"], "expected": "тост 3 с", "actual": "0,2 с", "repro": {"url": "https://example.com/a", "js": "true"}, "dup_check": "done",
  "clips": ["clips/T-01-raw.webm", "OUTSIDE", "clips/none.mp4", "screenshots/F-001-menu-annotated.png"]}]}
```
EOF
  sed -i.bak "s#OUTSIDE#$TMP/outside.mp4#" "$TMP/msg.md"
  check "ingest_findings: clips — путь внутри <RUN_DIR> → запись (bytes, sha256, viewed false); вне прогона, нет файла, не ролик — не приняты с предупреждением" sh -c "
    '$PY' '$S/ingest_findings.py' '$R' --from '$TMP/msg.md' > '$TMP/ing.json'; test \$? = 0 &&
    '$PY' -c \"import json,sys; r=json.load(open(sys.argv[1])); w=' '.join(r['warnings']); assert 'вне папки прогона' in w and 'не найден' in w and 'не ролик' in w, w
f=[x for x in json.load(open(sys.argv[2]))['findings'] if x['title']=='Тост исчезает мгновенно'][0]
assert len(f['clips'])==1 and f['clips'][0]['file']=='clips/T-01-raw.webm' and f['clips'][0]['sha256'] and f['clips'][0]['viewed'] is False and f['recordings']==['clips/T-01-raw.webm'], f
t=json.load(open(sys.argv[3])); assert t[0]['clips'][0]['file']=='clips/T-01-raw.webm', t\" '$TMP/ing.json' '$R/findings.json' '$R/findings/qa-ux.json'"
  printf 'version: 1\nclips:\n  max_mb: 0.2\n' > "$R/run-config.yaml"
  head -c 400000 /dev/urandom > "$R/clips/T-02-big.mp4"
  sed -e 's#Тост исчезает мгновенно#Большой ролик#' -e 's#"clips": \[[^]]*\]#"clips": ["clips/T-02-big.mp4"]#' "$TMP/msg.md" > "$TMP/msg2.md"
  check "ingest_findings: ролик больше бюджета ×1,05 — принят с предупреждением; --dry-run — только предупреждения" sh -c "
    '$PY' '$S/ingest_findings.py' '$R' --from '$TMP/msg2.md' --dry-run | grep -q 'больше бюджета' &&
    ! grep -q 'Большой ролик' '$R/findings.json' &&
    '$PY' '$S/ingest_findings.py' '$R' --from '$TMP/msg2.md' | grep -q 'больше бюджета' && grep -q 'clips/T-02-big.mp4' '$R/findings.json'"
  check "validate_findings: findings.json с роликами валиден по схеме" "$PY" "$S/validate_findings.py" "$R/findings.json"
else
  sk "видео-проверки clips.py / ingest / build_report / render_draft / publish_shots / export_results: нет ffmpeg (brew install ffmpeg)"
fi

# ---------- check_env ----------
H="$TMP/home"; mkdir -p "$H"
HOME="$H" "$PY" "$S/check_env.py" --fast --no-browsers --cdp-ports 1 --json "$TMP/env.json" > "$TMP/env.out" 2>&1
check "check_env: строки ffmpeg, ffprobe и Playwright screencast; env.json → clips" sh -c "
  grep -q '^| ffmpeg |' '$TMP/env.out' && grep -q '^| ffprobe |' '$TMP/env.out' && grep -q 'рекомендуется' '$TMP/env.out' &&
  '$PY' -c \"import json,sys; c=json.load(open(sys.argv[1]))['clips']; assert 'ffmpeg' in c and 'screencast' in c, c\" '$TMP/env.json'"
check "check_env без ffmpeg в PATH: WARN с командой установки (не FAIL, Итог не меняется из-за ffmpeg)" sh -c "
  mkdir -p '$TMP/bin' && for t in git node npm npx '$PY' gh claude playwright-cli; do p=\$(command -v \$t) && ln -sf \"\$p\" '$TMP/bin/'\$(basename \$t); done;
  HOME='$H' PATH='$TMP/bin:/usr/bin:/bin' QA_FFMPEG= QA_FFPROBE= PLAYWRIGHT_BROWSERS_PATH='$TMP/none' '$TMP/bin/'\$(basename '$PY') '$S/check_env.py' --fast --no-browsers --cdp-ports 1 > '$TMP/env2.out' 2>&1;
  if command -v ffmpeg | grep -q '^/usr/bin/'; then exit 0; fi;
  grep '^| ffmpeg |' '$TMP/env2.out' | grep -q 'WARN' && grep '^| ffmpeg |' '$TMP/env2.out' | grep -Eq 'brew install ffmpeg|apt install ffmpeg|winget install' &&
  ! grep -q 'нужно исправить:.*ffmpeg' '$TMP/env2.out'"

echo "stream v1.7.0: PASS $pass, FAIL $fail, SKIP $skip"
[ $fail -eq 0 ]
